    private static void prepare(Minecraft mc){var p=player(mc);p.setNoGravity(true);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.teleportTo(p.serverLevel(),.5,201,-3.5,0,10);if(RESUME)return;p.setGameMode(GameType.CREATIVE);for(int x=-5;x<=6;x++)for(int z=-5;z<=5;z++)p.serverLevel().setBlockAndUpdate(CORE.offset(x,-1,z),net.minecraft.world.level.block.Blocks.GRASS_BLOCK.defaultBlockState());p.serverLevel().setBlockAndUpdate(CORE,WuXingBlocks.ALCHEMY_FURNACE.get().defaultBlockState());CoreStructureBuilder.build(p,CORE);AlchemyFurnaceStructure.refreshAround(p.serverLevel(),CORE);check(AlchemyFurnaceBlock.isFormed(p.serverLevel().getBlockState(CORE)),"Furnace not formed");p.getInventory().clearContent();int index=0;for(var pill:PillCatalog.values()){var old=MedicineTier.set(PillData.create(pill,PillData.Grade.values()[index%4],PillData.Element.WATER,0),index%5+1);old.setCount(pill==PillCatalog.GOLDEN_WOUND?2:1);old.getOrCreateTag().putString("MigrationMarker",pill.id);p.getInventory().setItem(index++,old);}var creation=new ItemStack(WuXingItems.CREATION_PILL.get());creation.getOrCreateTag().putString("MigrationMarker","creation_pill");p.getInventory().setItem(index,creation);GeneratedMod.data(p).wuxingxiantu$setRealm(8);GeneratedMod.data(p).wuxingxiantu$learnFire(1);FormulaKnowledge.learnAll(p);p.serverLevel().setBlockAndUpdate(CHEST,net.minecraft.world.level.block.Blocks.CHEST.defaultBlockState());var old=new CompoundTag();old.putString("id","wuxingxiantu:root_water_perfect");old.putByte("Count",(byte)3);var tag=new CompoundTag();tag.putString("MigrationMarker","chest-legacy");old.put("tag",tag);((net.minecraft.world.level.block.entity.ChestBlockEntity)p.serverLevel().getBlockEntity(CHEST)).setItem(0,ItemStack.of(old));p.setGameMode(GameType.SURVIVAL);p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.getInventory().selected=1;p.inventoryMenu.broadcastChanges();}
    private static void verifyImports(Minecraft mc){var p=player(mc);int count=0;for(var item:p.getInventory().items)if(item.hasTag()&&item.getTag().contains("MigrationMarker")&&!item.getTag().getString("MigrationMarker").equals("chest-legacy")){check(item.is(WuXingItems.V5_PILL.get())&&!item.getTag().contains("Grade")&&!item.getTag().contains(MedicineTier.KEY),"An old active pill field remains");var doc=new BatchJournal(p.server).imported(item.getTag().getUUID(V5Batch.KEY));LegacyPillImport.validate(doc);check(doc.getCompound("Original").getCompound("tag").getString("MigrationMarker").equals(item.getTag().getString("MigrationMarker")),"Original metadata backup lost");count++;}check(count==23,"Migration type coverage "+count);check(AlchemyCertification.certifiedRank(p)==0,"Import or single nine-grade granted profession certification");}
